--
-- Table structure for table `hotels`
--

DROP TABLE IF EXISTS `hotels`;
CREATE TABLE IF NOT EXISTS `hotels` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `nom_hotel` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description_hotel` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `logo` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ville` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `localisation` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `telephone` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `services` json DEFAULT NULL,
  `bannier1` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bannier2` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bannier3` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
